// Toll passes (TEC-725, docs/design/tolls.md). Every query names the
// organization. Branch scope: a pass is visible when its vehicle's home or
// current branch, or its rental's planned pick-up / return or actual
// return branch, is in the member's scope (branch_ids NULL = every
// branch). A pass without a vehicle and a rental is visible to members of
// every branch only.
func (q *Queries) ListTollPasses(ctx context.Context, arg ListTollPassesParams) ([]ListTollPassesRow, error) {
	rows, err := q.db.Query(ctx, listTollPasses,
		arg.OrganizationID,
		arg.BranchIds,
		arg.Statuses,
		arg.Sources,
		arg.Providers,
		arg.ReviewReasons,
		arg.VehicleUuids,
		arg.RentalUuids,
		arg.HasRental,
		arg.PassedFrom,
		arg.PassedTo,
		arg.Q,
		arg.SortField,
		arg.SortDesc,
		arg.OffsetCount,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTollPassesRow{}
	for rows.Next() {
		var i ListTollPassesRow
		if err := rows.Scan(
			&i.Uuid,
			&i.Provider,
			&i.ExternalID,
			&i.Source,
			&i.PassedAt,
			&i.Plate,
			&i.TagNumber,
			&i.Station,
			&i.ExitStation,
			&i.Currency,
			&i.Amount,
			&i.Status,
			&i.ReviewReason,
			&i.MatchMethod,
			&i.Manual,
			&i.Revision,
			&i.LastFetchedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.VehicleUuid,
			&i.VehiclePlate,
			&i.RentalUuid,
			&i.RentalReference,
			&i.RentalStatus,
			&i.FeeAmount,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

