const updateTollPassFacts = `-- name: UpdateTollPassFacts :exec
UPDATE toll_passes
SET passed_at = $1, plate = $2, tag_number = $3,
    station = $4, exit_station = $5, currency = $6,
    amount = $7, raw = $8, revision = $9, source = $10,
    integration_account_id = COALESCE($11, integration_account_id),
    last_fetched_at = NOW()
WHERE organization_id = $12
  AND id = $13
`

type UpdateTollPassFactsParams struct {
	PassedAt             pgtype.Timestamptz `json:"passed_at"`
	Plate                string             `json:"plate"`
	TagNumber            string             `json:"tag_number"`
	Station              string             `json:"station"`
	ExitStation          string             `json:"exit_station"`
	Currency             string             `json:"currency"`
	Amount               pgtype.Numeric     `json:"amount"`
	Raw                  []byte             `json:"raw"`
	Revision             int32              `json:"revision"`
	Source               string             `json:"source"`
	IntegrationAccountID pgtype.Int8        `json:"integration_account_id"`
	OrganizationID       int64              `json:"organization_id"`
	ID                   int64              `json:"id"`
}

// A pass that arrived again with changed facts (a new revision).
func (q *Queries) UpdateTollPassFacts(ctx context.Context, arg UpdateTollPassFactsParams) error {
	_, err := q.db.Exec(ctx, updateTollPassFacts,
		arg.PassedAt,
		arg.Plate,
		arg.TagNumber,
		arg.Station,
		arg.ExitStation,
		arg.Currency,
		arg.Amount,
		arg.Raw,
		arg.Revision,
		arg.Source,
		arg.IntegrationAccountID,
		arg.OrganizationID,
		arg.ID,
	)
	return err
}

const updateVehicleTollTag = `-- name: UpdateVehicleTollTag :execrows
UPDATE vehicle_toll_tags
SET provider = $1, network = $2, tag_number = $3,
    valid_from = $4, valid_to = $5, note = $6
WHERE organization_id = $7
  AND id = $8
`

type UpdateVehicleTollTagParams struct {
	Provider       string             `json:"provider"`
	Network        string             `json:"network"`
	TagNumber      string             `json:"tag_number"`
	ValidFrom      pgtype.Timestamptz `json:"valid_from"`
	ValidTo        pgtype.Timestamptz `json:"valid_to"`
	Note           string             `json:"note"`
	OrganizationID int64              `json:"organization_id"`
	ID             int64              `json:"id"`
}

func (q *Queries) UpdateVehicleTollTag(ctx context.Context, arg UpdateVehicleTollTagParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateVehicleTollTag,
		arg.Provider,
		arg.Network,
		arg.TagNumber,
		arg.ValidFrom,
		arg.ValidTo,
		arg.Note,
		arg.OrganizationID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertTollSettings = `-- name: UpsertTollSettings :one
INSERT INTO toll_settings (organization_id, processing_fee, currency, auto_fetch, lookback_days, updated_by)
VALUES (
    $1, $2, $3, $4,
    $5, $6
)
ON CONFLICT (organization_id) DO UPDATE
SET processing_fee = EXCLUDED.processing_fee, currency = EXCLUDED.currency, auto_fetch = EXCLUDED.auto_fetch,
    lookback_days = EXCLUDED.lookback_days, updated_by = EXCLUDED.updated_by
RETURNING processing_fee, currency, auto_fetch, lookback_days, updated_at
`

type UpsertTollSettingsParams struct {
	OrganizationID int64          `json:"organization_id"`
	ProcessingFee  pgtype.Numeric `json:"processing_fee"`
	Currency       string         `json:"currency"`
	AutoFetch      bool           `json:"auto_fetch"`
	LookbackDays   int32          `json:"lookback_days"`
	UpdatedBy      pgtype.Int8    `json:"updated_by"`
}

type UpsertTollSettingsRow struct {
	ProcessingFee pgtype.Numeric     `json:"processing_fee"`
	Currency      string             `json:"currency"`
	AutoFetch     bool               `json:"auto_fetch"`
	LookbackDays  int32              `json:"lookback_days"`
	UpdatedAt     pgtype.Timestamptz `json:"updated_at"`
}

func (q *Queries) UpsertTollSettings(ctx context.Context, arg UpsertTollSettingsParams) (UpsertTollSettingsRow, error) {
	row := q.db.QueryRow(ctx, upsertTollSettings,
		arg.OrganizationID,
		arg.ProcessingFee,
		arg.Currency,
		arg.AutoFetch,
		arg.LookbackDays,
		arg.UpdatedBy,
	)
	var i UpsertTollSettingsRow
	err := row.Scan(
		&i.ProcessingFee,
		&i.Currency,
		&i.AutoFetch,
		&i.LookbackDays,
		&i.UpdatedAt,
	)
	return i, err
}
